INSERT INTO `oc_modification` VALUES (1,'Advanced Newsletter Subscribe PRO','adv_newsletter','anh.to87@gmail.com','1.0','http://www.opcartstore.com','<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<modification>\n    <name>Advanced Newsletter Subscribe PRO</name>\n    <code>adv_newsletter</code>\n    <version>1.0</version>\n    <author>anh.to87@gmail.com</author>\n    <link>http://www.opcartstore.com</link>\n    <file path=\"admin/model/module/adv_newsletter.php\">\n        <operation error=\"continue\">\n            <search><![CDATA[public function getEmails($data = array()) {]]></search>\n            <add position=\"before\"><![CDATA[\n    public function localCheck()\n    {\n        try {\n            new ReflectionMethod(\'ControllerModuleAdvancedNewsletter\', \'_beforeRender\');\n            return true;\n        } catch(ReflectionException $e) {\n            return false;\n        }\n    }\n            ]]></add>\n        </operation>\n    </file>\n</modification>',1,'2017-04-10 18:11:11'),(2,'Local copy OCMOD by iSenseLabs','isensealabs_quickfix_ocmod','iSenseLabs','1.3','http://isenselabs.com','<modification>\r\n    <name>Local copy OCMOD by iSenseLabs</name>\r\n	<version>1.3</version>\r\n	<link>http://isenselabs.com</link>\r\n	<author>iSenseLabs</author>\r\n	<code>isensealabs_quickfix_ocmod</code>\r\n\r\n	<file path=\"admin/controller/extension/installer.php\">\r\n		<operation error=\"skip\">\r\n			<search ><![CDATA[\'url\'  => str_replace(\'&amp;\', \'&\', $this->url->link(\'extension/installer/ftp\', \'token=\' . $this->session->data[\'token\'],]]></search>\r\n			<add position=\"replace\"><![CDATA[\'url\'  => str_replace(\'&amp;\', \'&\', $this->url->link(\'extension/installer/localcopy\', \'token=\' . $this->session->data[\'token\'],]]></add>\r\n		</operation>\r\n\r\n		<operation>\r\n			<search><![CDATA[public function unzip() {]]></search>\r\n			<add position=\"before\"><![CDATA[			\r\n	public function localcopy() {\r\n		$this->load->language(\'extension/installer\');\r\n\r\n		$json = array();\r\n\r\n		if (!$this->user->hasPermission(\'modify\', \'extension/installer\')) {\r\n			$json[\'error\'] = $this->language->get(\'error_permission\');\r\n		}\r\n\r\n		if (VERSION == \'2.0.0.0\') {\r\n		    $directory = DIR_DOWNLOAD  . str_replace(array(\'../\', \'..\\\\\', \'..\'), \'\', $this->request->post[\'path\']) . \'/upload/\';\r\n		} else {\r\n		    $directory = DIR_UPLOAD  . str_replace(array(\'../\', \'..\\\\\', \'..\'), \'\', $this->request->post[\'path\']) . \'/upload/\';\r\n		}\r\n\r\n		if (!is_dir($directory)) {\r\n			$json[\'error\'] = $this->language->get(\'error_directory\');\r\n		}\r\n\r\n		if (!$json) {\r\n			// Get a list of files ready to upload\r\n			$files = array();\r\n\r\n			$path = array($directory . \'*\');\r\n\r\n			while (count($path) != 0) {\r\n				$next = array_shift($path);\r\n\r\n				foreach (glob($next) as $file) {\r\n					if (is_dir($file)) {\r\n						$path[] = $file . \'/*\';\r\n					}\r\n\r\n					$files[] = $file;\r\n				}\r\n			}\r\n\r\n			$root = dirname(DIR_APPLICATION).\'/\';\r\n\r\n			foreach ($files as $file) {\r\n				// Upload everything in the upload directory\r\n				$destination = substr($file, strlen($directory));\r\n\r\n				// Update from newer OpenCart versions:\r\n				if (substr($destination, 0, 5) == \'admin\') {\r\n					$destination = DIR_APPLICATION . substr($destination, 5);\r\n				} else if (substr($destination, 0, 7) == \'catalog\') {\r\n					$destination = DIR_CATALOG . substr($destination, 7);\r\n				} else if (substr($destination, 0, 5) == \'image\') {\r\n					$destination = DIR_IMAGE . substr($destination, 5);\r\n				} else if (substr($destination, 0, 6) == \'system\') {\r\n					$destination = DIR_SYSTEM . substr($destination, 6);\r\n				} else {\r\n					$destination = $root.$destination;\r\n				}\r\n\r\n				if (is_dir($file)) {\r\n					if (!file_exists($destination)) {\r\n						if (!mkdir($destination)) {\r\n							$json[\'error\'] = sprintf($this->language->get(\'error_ftp_directory\'), $destination);\r\n						}\r\n					}\r\n				}\r\n\r\n				if (is_file($file)) {\r\n					if (!copy($file, $destination)) {\r\n						$json[\'error\'] = sprintf($this->language->get(\'error_ftp_file\'), $file);\r\n					}\r\n				}\r\n			}\r\n		}\r\n\r\n		$this->response->addHeader(\'Content-Type: application/json\');\r\n		$this->response->setOutput(json_encode($json));\r\n	}]]></add>\r\n		</operation>\r\n	</file>	\r\n</modification>\r\n',1,'2017-04-24 18:55:55'),(3,'All In One Seo For Opencart : Build Smart','allinoneseo','nerdherd.in','34.1','http://store.nerdherd.in/','<modification>\n	<name>All In One Seo For Opencart : Build Smart</name>\n	<version>34.1</version>\n	<link>http://store.nerdherd.in/</link>\n	<author>nerdherd.in</author>\n	<code>allinoneseo</code>\n	<file path=\"catalog/controller/product/category.php\">\n		<operation>\n			<search><![CDATA[if ($page == 1) {]]></search>\n			<add position=\"before\"><![CDATA[\n				if($this->config->get(\"nerdherd_direct_links\")) {\n					$category_info[\'category_id\'] = $category_id;\n				} else {\n					$category_info[\'category_id\'] = $this->request->get[\'path\'];\n				}\n				]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/error/not_found.php\">\n		<operation>\n			<search><![CDATA[$data[\'header\'] = $this->load->controller(\'common/header\');]]></search>\n			<add position=\"before\"><![CDATA[ \n          	if ($this->request->server[\'HTTPS\']) {\n			  $url = \'https://\'.$_SERVER[\'SERVER_NAME\'].$_SERVER[\'REQUEST_URI\'];\n			} else {\n			  $url = \'http://\'.$_SERVER[\'SERVER_NAME\'].$_SERVER[\'REQUEST_URI\'];\n			}\n\n			if ((strpos($url,\'.js\') == \'\') && (strpos($url,\'.css\') == \'\') ){\n			   $this->load->model(\'tool/redirect\');\n			   $this->model_tool_redirect->redirectData($url);\n			}\n  		]]>\n			</add>\n		</operation>\n		<operation>\n			<search><![CDATA[public function index() {]]></search>\n			<add position=\"after\"><![CDATA[if($this->config->get(\'config_redirect_status\')) {\n          if ($this->request->server[\'HTTPS\']) {\n              $url1 = \'https://\'.$_SERVER[\'SERVER_NAME\'].$_SERVER[\'REQUEST_URI\'];\n          } else {\n              $url1 = \'http://\'.$_SERVER[\'SERVER_NAME\'].$_SERVER[\'REQUEST_URI\'];\n          }\n          //$url1 = str_replace(\"&\", \"&amp;\", $url1);\n          $query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"redirect_manager WHERE fromUrl = \'\" .$this->db->escape($url1).\"\' and status = 1\");\n          if($query->num_rows) {\n            $this->db->query(\"UPDATE \" . DB_PREFIX . \"redirect_manager SET times_used = times_used + \'1\' WHERE fromUrl = \'\" .$this->db->escape($url1).\"\'\");\n            $mode = \'301 Moved Permanently\';\n            header(\"HTTP/1.1 \".$mode); \n            header(\"Location:\".str_replace(\"amp;\", \"\", $query->row[\'toUrl\']));\n            exit;\n          }\n      }\n]]>\n			</add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/product/category.php\">\n		<operation>\n			<search><![CDATA[$data[\'products\'][]]]></search>\n			<add position=\"before\"><![CDATA[if($this->config->get(\"nerdherd_direct_links\")) {\n	$link = $this->url->link(\'product/product\',\'product_id=\' . $result[\'product_id\'],\'SSL\');\n} else {\n    $link = $this->url->link(\'product/product\',\'path=\' . $this->request->get[\'path\'] . \'&product_id=\' . $result[\'product_id\'] . $url,\'SSL\');\n} ]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[$this->url->link(\'product/product\', \'path=\' . $this->request->get[\'path\'] . \'&product_id=\' . $result[\'product_id\'] . $url)]]></search>\n			<add position=\"replace\"><![CDATA[$link]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[$data[\'categories\'][]]]></search>\n			<add position=\"before\"><![CDATA[if($this->config->get(\"nerdherd_direct_links\")) {\n	$link = $this->url->link(\'product/category\', \'path=\' . $result[\'category_id\'],\'SSL\');\n} else {\n    $link = $this->url->link(\'product/category\',\'path=\' . $this->request->get[\'path\'] . \'_\' . $result[\'category_id\'] . $url,\'SSL\');\n} ]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[$this->url->link(\'product/category\', \'path=\' . $this->request->get[\'path\'] . \'_\' . $result[\'category_id\'] . $url)]]></search>\n			<add position=\"replace\"><![CDATA[$link]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/module/category.php\">\n		<operation>\n			<search><![CDATA[$children_data[]]]></search>\n			<add position=\"before\"><![CDATA[if($this->config->get(\"nerdherd_direct_links\")) {\n	$link = $this->url->link(\'product/category\', \'path=\' . $child[\'category_id\'],\'SSL\');\n} else {\n    $link = $this->url->link(\'product/category\',\'path=\' . $category[\'category_id\'] . \'_\' . $child[\'category_id\'],\'SSL\');\n} ]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[$this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'] . \'_\' . $child[\'category_id\'])]]></search>\n			<add position=\"replace\"><![CDATA[$link]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/product/manufacturer.php\">\n		<operation>\n			<search><![CDATA[\'href\'        => $this->url->link(\'product/product\', \'manufacturer_id=\' . $result[\'manufacturer_id\'] . \'&product_id=\' . $result[\'product_id\'] . $url)]]></search>\n			<add position=\"replace\"><![CDATA[\'href\'        => $link]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[$data[\'products\'][] = array(]]></search>\n			<add position=\"before\"><![CDATA[if($this->config->get(\"nerdherd_direct_links\")) {\n	$link = $this->url->link(\'product/product\', \'product_id=\' . $result[\'product_id\'],\'SSL\');\n} else {\n    $link =  $this->url->link(\'product/product\', \'manufacturer_id=\' . $result[\'manufacturer_id\'] . \'&product_id=\' . $result[\'product_id\'] . $url);\n} ]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/model/catalog/review.php\">\n			<operation>\n				<search><![CDATA[public function addReview(]]>\n				</search>\n				<add position=\"before\">\n					<![CDATA[\n					public function getAllReviewsByProductId($product_id) {	\n			\n			$query = $this->db->query(\"SELECT r.review_id, r.author, r.rating, r.text, p.product_id, pd.name, p.price, p.image, r.date_added FROM \" . DB_PREFIX . \"review r LEFT JOIN \" . DB_PREFIX . \"product p ON (r.product_id = p.product_id) LEFT JOIN \" . DB_PREFIX . \"product_description pd ON (p.product_id = pd.product_id) WHERE p.product_id = \'\" . (int)$product_id . \"\' AND p.date_available <= NOW() AND p.status = \'1\' AND r.status = \'1\' AND pd.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' ORDER BY r.date_added DESC\");\n				\n			return $query->rows;\n		}\n\n		public function getcategory($product_id) {\n			$query = $this->db->query(\"SELECT cd.name FROM \" . DB_PREFIX . \"product_to_category p2c  LEFT JOIN \" . DB_PREFIX . \"category_description  cd ON (p2c.category_id = cd.category_id) WHERE p2c.product_id = \'\" . (int)$product_id . \"\' AND cd.language_id = \'\".(int)$this->config->get(\'config_language_id\').\"\' ORDER BY p2c.category_id ASC LIMIT 1\");\n\n			return isset($query->row[\'name\']) ? $query->row[\'name\'] : \"\";\n		}\n					]]>\n				</add>\n			</operation>\n		</file>\n		<file path=\"catalog/controller/product/product.php\">\n			<operation>\n			<search><![CDATA[\n			$data[\'images\'] = array();\n			]]></search>\n				<add position=\"before\"><![CDATA[\n				$this->load->language(\"tool/seo\");\n				\n				if ($product_info[\'image\']) {\n					$data[\'popuppin\'] = $this->model_tool_image->resize($product_info[\'image\'], $this->language->get(\'google_image_width\'), $this->language->get(\'google_image_height\'));\n				} else {\n					$data[\'popuppin\'] = \'\';\n				}\n					\n				$this->session->data[\'pimage\'] = $data[\'popuppin\'];\n				$this->load->model(\'localisation/currency\');\n				$data[\'currencies\'] = array();\n				$cresults = $this->model_localisation_currency->getCurrencies();\n				if ((float)$product_info[\'special\']) {\n					$this->session->data[\'pprice\'] = $this->tax->calculate($product_info[\'special\'], $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\'));\n					foreach ($cresults as $result) {\n						if ($result[\'status\']) {\n							$data[\'pcurrencies\'][] = array(\n								\'code\'         => $result[\'code\'],\n								\'price\'        => $this->tax->calculate(($result[\'value\'] * $product_info[\'special\']), $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\'))\n							);\n						}\n					}\n				} else {\n					$this->session->data[\'pprice\'] = $this->tax->calculate($product_info[\'price\'], $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\'));\n					foreach ($cresults as $result) {\n						if ($result[\'status\']) {\n							$data[\'pcurrencies\'][] = array(\n								\'code\'         => $result[\'code\'],\n								\'price\'        => $this->tax->calculate(($result[\'value\'] * $product_info[\'price\']), $product_info[\'tax_class_id\'], $this->config->get(\'config_tax\'))\n							);\n						}\n					}\n				}\n				$data[\'meta_description\'] = $product_info[\'meta_description\'];\n				$this->session->data[\'pmodel\'] = $product_info[\'model\'];\n				$this->session->data[\'pstock\'] = $product_info[\'quantity\'];\n				$data[\'pstock\'] = $product_info[\'quantity\'];\n				$this->session->data[\'pmodel\'] = $product_info[\'model\'];\n				$this->session->data[\'pbrand\'] = $product_info[\'manufacturer\'];\n				$data[\'prating\'] = (int)$product_info[\'rating\'];\n				$data[\'ptotalreviews\'] = sprintf((int)$product_info[\'reviews\']);\n				$this->session->data[\'plink\'] = $this->url->link(\'product/product\', \'product_id=\' . $this->request->get[\'product_id\']);\n				$data[\'plink\'] = $this->session->data[\'plink\'];\n				$data[\'pprice\'] = $this->session->data[\'pprice\'];\n				$data[\'config_currency\'] = $this->config->get(\'config_currency\');\n				$data[\'config_gr_status\'] = $this->config->get(\'grsnippetgoogle_status\');\n				$this->load->model(\'catalog/review\');\n				$data[\'config_name\'] = $this->config->get(\'config_name\');\n				$data[\'reviewresults\'] = $this->model_catalog_review->getAllReviewsByProductId($this->request->get[\'product_id\']);\n\n				if ($product_info[\'image\']) {\n					if($this->config->get(\'grsnippetfacebook_status\') && $this->config->get(\'grsnippetpinterest_status\')) {\n						$data[\'pinimage\'] = $this->model_tool_image->resize($product_info[\'image\'],$this->language->get(\'mix_image_width\'), $this->language->get(\'mix_image_height\'));\n					} else if($this->config->get(\'grsnippetfacebook_status\')) {\n						$data[\'pinimage\'] = $this->model_tool_image->resize($product_info[\'image\'],$this->language->get(\'facebook_image_width\'), $this->language->get(\'facebook_image_height\'));\n					} else {\n						$data[\'pinimage\'] = $this->model_tool_image->resize($product_info[\'image\'],$this->language->get(\'pinterest_image_width\'), $this->language->get(\'pinterest_image_height\'));\n					}\n				} else {\n					$data[\'pinimage\'] = \'\';\n				}\n				$this->session->data[\'pinimage\'] = $data[\'pinimage\'];\n\n				if ($product_info[\'image\']) {\n					if($this->config->get(\'config_twitter_cardsize\')) {\n						$data[\'twitimage\'] = $this->model_tool_image->resize($product_info[\'image\'], $this->language->get(\'twitter_image_width\'), $this->language->get(\'twitter_image_height\'));\n					} else {\n						$data[\'twitimage\'] = $this->model_tool_image->resize($product_info[\'image\'], $this->language->get(\'twitter_imagesmall_width\'), $this->language->get(\'twitter_imagesmall_height\'));\n					}\n				} else {\n					$data[\'twitimage\'] = \'\';\n				}\n				$this->session->data[\'twitimage\'] = $data[\'twitimage\'];\n\n				]]></add>\n			</operation>\n		</file>\n		<file path=\"catalog/controller/product/product.php\">\n			<operation>\n				<search><![CDATA[if (isset($this->request->get[\'product_id\'])) {]]>\n				</search>\n				<add position=\"before\"><![CDATA[\n				if($this->config->get(\"nerdherd_breadcrumblink\") || $this->config->get(\"nerdherd_manu_breadcrumblink\")) {\n					$data[\'breadcrumbs\'] = array();\n\n					$data[\'breadcrumbs\'][] = array(\n						\'text\' => $this->language->get(\'text_home\'),\n						\'href\' => $this->url->link(\'common/home\')\n					);\n\n				$this->load->model(\'catalog/product\');\n				if($this->config->get(\"nerdherd_breadcrumblink\")) {\n					\n					$breadcats =  $this->model_catalog_product->getBreadCategories($this->request->get[\'product_id\']);\n					foreach ($breadcats as $key => $value) {\n						$data[\'breadcrumbs\'][] = array(\n							\'text\'      => $value[\'name\'],\n							\'href\'      => $this->url->link(\'product/category\', \'path=\' . $value[\'category_id\']),\n							\'separator\' => $this->language->get(\'text_separator\')\n						);\n					}\n					\n				}\n\n				if($this->config->get(\"nerdherd_manu_breadcrumblink\")) {\n					\n					$breadmanu =  $this->model_catalog_product->getBreadManu($this->request->get[\'product_id\']);\n					if (!empty($breadmanu)) {\n						$data[\'breadcrumbs\'][] = array(\n							\'text\'      => $breadmanu[\'name\'],\n							\'href\'      => $this->url->link(\'product/manufacturer/info\', \'manufacturer_id=\' . $breadmanu[\'manufacturer_id\']),\n							\'separator\' => $this->language->get(\'text_separator\')\n						);\n					}\n					\n				}\n\n				\n			}]]>\n				</add>\n			</operation>\n		</file>\n		<file path=\"catalog/model/catalog/product.php\">\n			<operation>\n				<search><![CDATA[public function getTotalProducts($data]]>\n				</search>\n				<add position=\"before\"><![CDATA[public function getBreadCategories($product_id) {\n			$return_data = array();\n			$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"product_to_category WHERE product_id = \'\" . (int)$product_id . \"\' ORDER BY category_id DESC LIMIT 1 \");\n			\n			if($query->num_rows == 1){\n				$return_data = $this->getparent($query->row[\'category_id\']);\n				$return_data = array_reverse($return_data);\n			}\n\n			return $return_data;\n		}\n\n		public function getBreadManu($product_id) {\n			$return_data = array();\n			$query = $this->db->query(\"SELECT p.manufacturer_id,m.name FROM \" . DB_PREFIX . \"product p LEFT JOIN  \" . DB_PREFIX . \"manufacturer m ON (p.manufacturer_id = m.manufacturer_id)  WHERE p.product_id = \'\" . (int)$product_id . \"\' LIMIT 1 \");\n			\n			if($query->num_rows == 1){\n				$return_data[\'name\'] = $query->row[\'name\'];\n				$return_data[\'manufacturer_id\'] = $query->row[\'manufacturer_id\'];\n			}\n\n			return $return_data;\n		}\n\n		public function getparent($cid) {\n			$data = array();\n			$temp  = $this->db->query(\"SELECT c.category_id, cd1.name AS name, c.parent_id FROM \" . DB_PREFIX . \"category c LEFT JOIN \" . DB_PREFIX . \"category_description cd1 ON (c.category_id = cd1.category_id)  WHERE cd1.language_id = \'\" . (int)$this->config->get(\'config_language_id\') . \"\' AND c.category_id = \'\".(int)$cid.\"\'\");\n			\n			if($temp->num_rows == 1) {\n				$data[] = $temp->row;\n				\n				if($temp->row[\'parent_id\'] != 0) {\n					$data = array_merge($data,  $this->getparent($temp->row[\'parent_id\']));\n				}\n			} else {\n				return $data;\n			}\n			return $data;\n		}\n		\n		]]>\n				</add>\n			</operation>\n		</file>\n	<file path=\"catalog/controller/common/header.php\">\n	<operation>\n		<search><![CDATA[$data[\'base\']]]>\n		</search>\n		<add position=\"before\"><![CDATA[\n	if(isset($this->session->data[\'plink\'])) {\n		$data[\'plink\'] = $this->session->data[\'plink\'];\n	} \n	unset($this->session->data[\'plink\']);\n\n\n	if(isset($this->session->data[\'pimage\'])) {\n		$data[\'pimage\'] = $this->session->data[\'pimage\'];\n	}\n	unset($this->session->data[\'pimage\']);\n\n	if(isset($this->session->data[\'twitimage\'])) {\n		$data[\'twitimage\'] = str_replace(\" \",\"%20\",$this->session->data[\'twitimage\']);\n	}\n	unset($this->session->data[\'twitimage\']);\n\n	if(isset($this->session->data[\'pinimage\'])) {\n		$data[\'pinimage\'] = str_replace(\" \",\"%20\",$this->session->data[\'pinimage\']);\n	}\n	unset($this->session->data[\'pinimage\']);\n\n	if(isset($this->session->data[\'pstock\'])) {\n	$data[\'pstock\'] = $this->session->data[\'pstock\'];\n	} \n	unset($this->session->data[\'pstock\']);\n\n\n	if(isset($this->session->data[\'pprice\'])) {\n		$data[\'pprice\'] = $this->session->data[\'pprice\'];\n	} \n	unset($this->session->data[\'pprice\']);\n\n	if(isset($this->session->data[\'pmodel\'])) {\n		$data[\'pmodel\'] = $this->session->data[\'pmodel\'];\n	} \n	unset($this->session->data[\'pmodel\']);\n\n	if(isset($this->session->data[\'pbrand\'])) {\n	$data[\'pbrand\'] = $this->session->data[\'pbrand\'];\n	} \n	unset($this->session->data[\'pbrand\']);\n\n	$data[\'config_name\'] = $this->config->get(\'config_name\');\n	$data[\'config_currency\'] = $this->config->get(\'config_currency\');\n\n	$data[\'config_google_pageid\'] = $this->config->get(\'config_google_pageid\');\n\n	$data[\'config_twitter_status\'] = $this->config->get(\'twittersnippet_status\');\n	$data[\'config_twitter_uername\'] = $this->config->get(\'config_twitter_uername\');\n	$data[\'tcardsize\'] = $this->config->get(\'config_twitter_cardsize\');\n\n	$data[\'config_facebook_status\'] = $this->config->get(\'grsnippetfacebook_status\');\n	$data[\'config_facebook_adminid\'] = $this->config->get(\'config_facebook_adminid\');\n\n	$data[\'config_pinterest_status\'] = $this->config->get(\'grsnippetpinterest_status\');\n\n	]]>\n				</add>\n			</operation>\n			<operation>\n			<search><![CDATA[$children_data[] = array(]]></search>\n			<add position=\"before\"><![CDATA[if($this->config->get(\"nerdherd_direct_links\")) {\n	$link = $this->url->link(\'product/category\', \'path=\' . $child[\'category_id\'],\'SSL\');\n} else {\n    $link = $this->url->link(\'product/category\',\'path=\' . $category[\'category_id\'] . \'_\' . $child[\'category_id\'],\'SSL\');\n} ]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[$this->url->link(\'product/category\', \'path=\' . $category[\'category_id\'] . \'_\' . $child[\'category_id\'])]]></search>\n			<add position=\"replace\"><![CDATA[$link]]></add>\n		</operation>\n		</file>\n	<file path=\"catalog/view/theme/*/template/common/header.tpl\">\n	<operation>\n	<search><![CDATA[<?php foreach ($links as $link) { ?>]]></search>\n	<add position=\"before\"><![CDATA[<?php if($config_google_pageid != \"\") { ?>\n		<link href=\"https://plus.google.com/<?php echo $config_google_pageid; ?>\" rel=\"publisher\" />\n	<?php } ?>\n	<?php if(isset($plink)  && ($config_facebook_status || $config_pinterest_status)) { ?>\n	<?php if(isset($pprice)) { ?>\n	<meta property=\"og:type\" content=\"og:product\" /> <?php } ?>			\n	<meta property=\"og:title\" content=\"<?php echo $title; ?>\" />\n	<?php if(isset($pinimage)) { ?>\n	<meta property=\"og:image\" content=\"<?php echo $pinimage; ?>\" />\n	<?php } ?>\n	<?php if($description != \"\") { ?>\n	<meta property=\"og:description\" content=\"<?php echo $description; ?>\" />\n	<?php } ?>\n	<meta property=\"og:url\" content=\"<?php echo $plink; ?>\" />\n	<?php if(isset($pprice) && ($config_facebook_status || $config_pinterest_status)) { ?>\n	<meta property=\"product:price:amount\" content=\"<?php echo $pprice; ?>\" />\n	<meta property=\"product:price:currency\" content=\"<?php echo $config_currency; ?>\" />\n	<meta property=\"og:price:amount\" content=\"<?php echo $pprice; ?>\" />\n	<meta property=\"og:price:currency\" content=\"<?php echo $config_currency; ?>\" />\n	<?php } ?>\n	<?php if(isset($pstock)) { ?>\n	<meta property=\"og:availability\" content=\"<?php echo ($pstock ? \'instock\' : \'out of stock\') ?>\" />\n	<?php } ?>\n	<?php if(isset($pbrand)) { ?>\n	<meta property=\"og:brand\" content=\"<?php echo $pbrand; ?>\" />\n	<?php } ?>\n	<meta property=\"og:site_name\" content=\"<?php echo $config_name; ?>\" />\n	<?php if($config_facebook_adminid != \"\") { ?>\n	<meta property=\"fb:admins\" content=\"<?php echo $config_facebook_adminid ?>\" />\n	<?php } ?>\n	<?php } ?>\n	<?php if(isset($pprice) && $config_twitter_uername != \"\" && $config_twitter_status) { ?>\n	<meta name=\"twitter:card\" content=\"<?php echo ( $tcardsize ? \"summary_large_image\" : \"summary\") ?>\" />\n	<meta name=\"twitter:site\" content=\"<?php echo $config_twitter_uername; ?>\" />\n	<meta name=\"twitter:title\" content=\"<?php echo $title; ?>\" />\n	<?php if($description != \"\") { ?>\n	<meta name=\"twitter:description\" content=\"<?php echo $description; ?>\" />\n	<?php } ?>\n	<?php if(isset($twitimage)) { ?>\n	<meta name=\"twitter:image\" content=\"<?php echo $twitimage; ?>\" />\n	<?php } ?>\n	<meta name=\"twitter:domain\" content=\"<?php echo $base; ?>\" />\n	<?php } ?>\n\n	]]></add>\n			</operation>\n	</file>\n	<file path=\"catalog/view/theme/*/template/product/product.tpl\">\n		<operation>\n		<search><![CDATA[<?php echo $footer; ?>]]></search>\n		<add position=\"before\"><![CDATA[\n			<?php if($config_gr_status) { ?>\n	<span itemscope itemtype=\"http://schema.org/Product\">\n		<meta itemprop=\"name\" content=\"<?php echo $heading_title; ?>\">\n		<meta itemprop=\"url\" content=\"<?php echo $plink; ?>\">\n		<?php if($meta_description != \"\") { ?><meta itemprop=\"description\" content=\"<?php echo $meta_description; ?>\" /><?php } ?>\n		<?php if(isset($pimage)) { ?><meta itemprop=\"image\" content=\"<?php echo str_replace(\" \",\"%20\",$pimage); ?>\" /><?php } ?>\n		<?php if($model != \"\") { ?><meta itemprop=\"model\" content=\"<?php echo $model; ?>\"><?php } ?>\n		<?php if($manufacturer != \"\") { ?><meta itemprop=\"brand\" content=\"<?php echo $manufacturer; ?>\"><?php } ?>\n	 	<?php foreach ($pcurrencies as $currency) { ?><span itemscope itemprop=\"offers\" itemtype=\"http://schema.org/Offer\">\n				<meta itemprop=\"price\" content=\"<?php echo $currency[\'price\']; ?>\">\n				<meta itemprop=\"priceCurrency\" content=\"<?php echo $currency[\'code\']; ?>\">\n				<meta itemprop=\"availability\" itemtype=\"http://schema.org/ItemAvailability\" content=\"http://schema.org/<?php echo ($pstock ? \"InStock\" : \"OutOfStock\") ?>\">\n				<meta itemprop=\"itemCondition\" content=\"http://schema.org/NewCondition\" />\n			</span>\n		<?php } ?>\n		<?php if(isset($ptotalreviews) && $ptotalreviews) { ?>\n			<span itemscope itemprop=\"aggregateRating\" itemtype=\"http://schema.org/AggregateRating\">\n				<meta itemprop=\"reviewCount\" content=\"<?php echo $ptotalreviews; ?>\">\n				<meta itemprop=\"ratingValue\" content=\"<?php echo $prating; ?>\">\n			</span>\n		<?php } ?>\n		<?php foreach($reviewresults as $result) { ?>\n			<span itemprop=\"review\" itemscope itemtype=\"http://schema.org/Review\" />\n				<meta itemprop=\"name\"  content = \"<?php echo substr($result[\'text\'], 0, 15); ?>\" />\n				<meta itemprop=\"description\" content = \"<?php echo $result[\'text\']; ?>\" />\n				<span itemprop=\"author\" itemscope itemtype=\"http://schema.org/Person\">\n				 	<meta itemprop=\"name\" content = \"<?php echo $result[\'author\']; ?>\" />\n				</span>\n				<meta itemprop=\"datePublished\" content=\"<?php echo date(\'Y-m-d\', strtotime($result[\'date_added\'])); ?>\" />\n				<span itemprop=\"reviewRating\" itemscope itemtype=\"http://schema.org/Rating\">\n					<meta itemprop=\"ratingValue\" content = \"<?php echo $result[\'rating\']; ?>\" />\n					<meta itemprop=\"bestRating\" content = \"5\" />\n					<meta itemprop=\"worstRating\" content=\"1\" />\n				</span>\n			</span>\n		<?php } ?>\n	</span>\n<?php } ?>]]></add>\n			</operation>\n						<operation>\n<search><![CDATA[<?php echo $footer; ?>]]></search>\n<add position=\"before\"><![CDATA[<?php if($config_gr_status) { ?><?php if(isset($breadcrumbs) && !empty($breadcrumbs)) { ?><script type=\"application/ld+json\">\n{\n\"@context\": \"http://schema.org\",\n\"@type\": \"BreadcrumbList\",\n\"itemListElement\": [\n<?php $temp = 0;end($breadcrumbs); $lastElement = key($breadcrumbs); foreach ($breadcrumbs as $key => $value) { $temp = $temp + 1;?>\n{\n\"@type\": \"ListItem\",\n\"position\": <?php echo $temp ?>,\n\"item\": {\n\"@id\": \"<?php echo $value[\'href\']; ?>\",\n\"name\": \"<?php echo strip_tags($value[\'text\']); ?>\"\n}  \n}<?php if($key == $lastElement) {}else{echo \",\";}?>\n<?php } ?>\n]\n}\n</script>\n<?php } ?>\n<?php } ?>\n]]></add>\n	</operation>\n		</file>\n		<file path=\"catalog/view/theme/*/template/common/language.tpl\">\n			<operation>\n			<search><![CDATA[<li><button class=\"btn btn-link btn-block language-select\" type=\"button\" name=\"<?php echo $language[\'code\']; ?>\"><img src=\"catalog/language/<?php echo $language[\'code\']; ?>/<?php echo $language[\'code\']; ?>.png\" alt=\"<?php echo $language[\'name\']; ?>\" title=\"<?php echo $language[\'name\']; ?>\" /> <?php echo $language[\'name\']; ?></button></li>]]></search>\n			<add position=\"replace\"><![CDATA[\n				<li><button  class=\"btn btn-link btn-block language-select\" onclick=\"$(\'input[name=\\\'redirect\\\']\').attr(\'value\', \'<?php echo $language[\'href\']; ?>\');\" type=\"button\" name=\"<?php echo $language[\'code\']; ?>\"><img src=\"catalog/language/<?php echo $language[\'code\']; ?>/<?php echo $language[\'code\']; ?>.png\" alt=\"<?php echo $language[\'name\']; ?>\" title=\"<?php echo $language[\'name\']; ?>\" /> <?php echo $language[\'name\']; ?></button></li>\n				]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[<li><a href=\"<?php echo $language[\'code\']; ?>\"><img src=\"image/flags/<?php echo $language[\'image\']; ?>\" alt=\"<?php echo $language[\'name\']; ?>\" title=\"<?php echo $language[\'name\']; ?>\" /> <?php echo $language[\'name\']; ?></a></li>]]></search>\n			<add position=\"replace\"><![CDATA[\n				<li><a href=\" href=\"<?php echo $language[\'code\']; ?>\" onclick=\"$(\'input[name=\\\'redirect\\\']\').attr(\'value\', \'<?php echo $language[\'href\']; ?>\');\"><img src=\"image/flags/<?php echo $language[\'image\']; ?>\" alt=\"<?php echo $language[\'name\']; ?>\" title=\"<?php echo $language[\'name\']; ?>\" /> <?php echo $language[\'name\']; ?></a></li>\n				]]></add>\n		</operation>\n		</file>\n		<file path=\"catalog/controller/common/language.php\">\n		<operation>\n			<search><![CDATA[foreach]]></search>\n			<add position=\"before\"><![CDATA[/*]]></add>\n		</operation>\n		<operation>\n			<search><![CDATA[if (!isset($this->request->get[\'route\'])) {]]></search>\n			<add position=\"before\"><![CDATA[*/\n				foreach ($results as $result) {\n			if (!isset($this->session->data[\'hreflang\'][$result[\'language_id\']])) {\n				if (isset($this->request->server[\'HTTPS\']) && (($this->request->server[\'HTTPS\'] == \'on\') || ($this->request->server[\'HTTPS\'] == \'1\'))) {\n					$this->session->data[\'hreflang\'][$result[\'language_id\']] = HTTPS_SERVER;\n				} else {\n					$this->session->data[\'hreflang\'][$result[\'language_id\']] = HTTP_SERVER;\n				}\n			}\n			if ($result[\'status\']) {\n				$data[\'languages\'][] = array(\n					\'name\'  => $result[\'name\'],\n					\'code\'  => $result[\'code\'],\n					\'href\'  => $this->session->data[\'hreflang\'][$result[\'language_id\']]\n				);\n			}\n		}\n		unset($this->session->data[\'hreflang\']);\n		]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/startup/startup.php\">\n		<operation>\n			<search><![CDATA[$customer = new Cart\\Customer($this->registry);]]>\n			</search>\n			<add position=\"before\"><![CDATA[          \n				if ((count($languages) > 1) && isset($this->request->get[\'_route_\'])) {\n	$parts = explode(\'/\', $this->request->get[\'_route_\']);\n	\n	// remove any empty arrays from trailing\n	if (utf8_strlen(end($parts)) == 0) {\n		array_pop($parts);\n	}\n\n	foreach ($parts as $part) {\n		$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"url_alias WHERE keyword = \'\" . $this->db->escape($part) . \"\'\");\n		if($query->num_rows) {\n			$codebasedonkeyword = \"\";\n			foreach ($languages as $key => $value) {\n				if($query->row[\'lang\'] == $value[\'language_id\']) {\n					$codebasedonkeyword = $key;\n				}\n			}\n			if($codebasedonkeyword) {\n				if($codebasedonkeyword != $code) {\n					if(array_key_exists($codebasedonkeyword, $languages)) {\n						$code = $codebasedonkeyword;\n						$this->session->data[\'language\'] = $code;\n						setcookie(\'language\', $code, time() + 60 * 60 * 24 * 30, \'/\', $this->request->server[\'HTTP_HOST\']);\n						$language = new Language($code);\n						$language->load($code);\n						$this->registry->set(\'language\', $language);\n						// Set the config language_id\n						$this->config->set(\'config_language_id\', $languages[$code][\'language_id\']);	\n					}\n				}\n			}\n		}\n	}\n}\n				]]>\n			</add>\n		</operation>\n	</file>	\n	<file path=\"catalog/controller/startup/seo_url.php\">\n		<operation>\n			<search><![CDATA[\n				if ($url[0] == \'information_id\') {\n				]]>\n			</search>\n			<add position=\"before\"><![CDATA[          \n				if($url[0] == \'route\') {\n						$this->request->get[\'route\'] = $url[1];\n					}\n				]]>\n			</add>\n		</operation>\n		<operation>\n			<search><![CDATA[\n				$this->request->get[\'route\'] = $query->row[\'query\'];\n				]]>\n			</search>\n			<add position=\"replace\"><![CDATA[          \n				if($url[0] != \'route\') {\n					$this->request->get[\'route\'] = $query->row[\'query\'];\n				}\n				]]>\n			</add>\n		</operation>\n		<operation>\n			<search><![CDATA[$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"url_alias WHERE `query` = \'\" . $this->db->escape($key . \'=\' . (int)$value) . \"\'\");]]>\n			</search>\n			<add position=\"replace\"><![CDATA[\n				if (($data[\'route\'] == \'product/product\' && $key == \'product_id\') || (($data[\'route\'] == \'product/manufacturer/info\' || $data[\'route\'] == \'product/product\') && $key == \'manufacturer_id\') || ($data[\'route\'] == \'information/information\' && $key == \'information_id\')) {\n					$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"url_alias WHERE `query` = \'\" . $this->db->escape($key . \'=\' . (int)$value) . \"\' AND lang = \'\".(int)$this->config->get(\'config_language_id\').\"\'\");\n				} else {\n					$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"url_alias WHERE `query` = \'\" . $this->db->escape($key . \'=\' . (int)$value) . \"\'\");\n				}\n			]]>\n			</add>\n		</operation>\n		<operation>\n			<search><![CDATA[$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"url_alias WHERE `query` = \'category_id=\" . (int)$category . \"\'\");]]>\n			</search>\n			<add position=\"replace\"><![CDATA[$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"url_alias WHERE `query` = \'category_id=\" . (int)$category . \"\'  AND lang = \'\".(int)$this->config->get(\'config_language_id\').\"\'\");]]>\n			</add>\n		</operation>\n		<operation>\n			<search><![CDATA[if ($url) {]]>\n			</search>\n			<add position=\"before\"><![CDATA[\n		 foreach ($data as $key => $value) {\n            \n				if (isset($data[\'route\'])) {\n				\n				    if($key = \'route\') {\n				    	$query = $this->db->query(\"SELECT * FROM `\" . DB_PREFIX . \"url_alias` WHERE `query` = \'route=\" . $this->db->escape($value) . \"\' AND lang = \'\".(int)$this->config->get(\'config_language_id\').\"\'\");\n				    	if($query->num_rows) {\n				    		$url .= \'/\' . $query->row[\'keyword\'];\n				    	}\n			        }				\n			    }\n			}\n			]]>\n			</add>\n		</operation>\n		<operation>\n			<search><![CDATA[\n					public function rewrite($link) {\n				]]>\n			</search>\n			<add position=\"before\"><![CDATA[ \npublic function nerdherd($link,$langid,$server){\n		$url_info = parse_url(str_replace(\'&amp;\', \'&\', $link));\n		$url = \'\'; \n		$data = array();\n		parse_str($url_info[\'query\'], $data);\n\n		foreach ($data as $key => $value) {\n			if (isset($data[\'route\'])) {\n				if (($data[\'route\'] == \'product/product\' && $key == \'product_id\') || (($data[\'route\'] == \'product/manufacturer/info\' || $data[\'route\'] == \'product/product\') && $key == \'manufacturer_id\') || ($data[\'route\'] == \'information/information\' && $key == \'information_id\')) {\n					$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"url_alias WHERE `query` = \'\" . $this->db->escape($key . \'=\' . (int)$value) . \"\' AND lang = \'\".(int)$langid.\"\'\");\n					if ($query->num_rows) {\n						$url .= \'/\' . $query->row[\'keyword\'];\n						unset($data[$key]);\n					}					\n				} elseif($key == \'path\'){\n					$categories = explode(\'_\', $value);\n					foreach ($categories as $category) {\n						$query = $this->db->query(\"SELECT * FROM \" . DB_PREFIX . \"url_alias WHERE `query` = \'category_id=\" . (int)$category . \"\' AND lang = \'\".(int)$langid.\"\'\");\n						if ($query->num_rows) {\n							$url .= \'/\' . $query->row[\'keyword\'];\n						}							\n					}\n					unset($data[$key]);\n				}\n			}\n		}\n\n		 foreach ($data as $key => $value) {\n            \n				if (isset($data[\'route\'])) {\n				\n				    if($key = \'route\') {\n				    	$query = $this->db->query(\"SELECT * FROM `\" . DB_PREFIX . \"url_alias` WHERE `query` = \'route=\" . $this->db->escape($value) . \"\' AND lang = \'\".(int)$langid.\"\'\");\n				    	if($query->num_rows) {\n				    		$url .= \'/\' . $query->row[\'keyword\'];\n				    	}\n			        }				\n			    }\n			}\n\n		if ($url) {\n			unset($data[\'route\']);\n			$query = \'\';\n			if ($data) {\n				foreach ($data as $key => $value) {\n					$query .= \'&\' . $key . \'=\' . $value;\n				}\n				if ($query) {\n					$query = \'?\' . trim($query, \'&\');\n				}\n			}\n			return $url_info[\'scheme\'] . \'://\' . $url_info[\'host\'] . (isset($url_info[\'port\']) ? \':\' . $url_info[\'port\'] : \'\') . str_replace(\'/index.php\', \'\', $url_info[\'path\']) . $url . $query;\n		} else {\n			return $link;\n		}\n	}\n	]]>\n			</add>\n		</operation>\n		<operation>\n			<search><![CDATA[if (!isset($this->request->get[\'route\'])) {]]>\n			</search>\n			<add position=\"before\"><![CDATA[\n			$this->load->model(\"localisation/language\");\n			$results = $this->model_localisation_language->getLanguages();\n\n			if (isset($this->request->server[\'HTTPS\']) && (($this->request->server[\'HTTPS\'] == \'on\') || ($this->request->server[\'HTTPS\'] == \'1\'))) {\n				$server = $this->config->get(\'config_ssl\');\n			} else {\n				$server = $this->config->get(\'config_url\');\n			}\n			if (isset($this->request->get[\'product_id\']) && isset($this->request->get[\'path\'])) {\n				foreach ($results as $key => $value){\n					$this->session->data[\'hreflang\'][$value[\'language_id\']] = $this->nerdherd($server.\"index.php?route=product/product&path=\".$this->request->get[\'path\'].\"&product_id=\".$this->request->get[\'product_id\'],$value[\'language_id\'],$server);\n				}\n			} elseif(isset($this->request->get[\'product_id\'])){\n				foreach ($results as $key => $value){\n					$this->session->data[\'hreflang\'][$value[\'language_id\']] = $this->nerdherd($server.\"index.php?route=product/product&product_id=\".$this->request->get[\'product_id\'],$value[\'language_id\'],$server);\n				}\n			} elseif(isset($this->request->get[\'path\'])){\n				foreach ($results as $key => $value){\n					$this->session->data[\'hreflang\'][$value[\'language_id\']] = $this->nerdherd($server.\"index.php?route=product/category&path=\".$this->request->get[\'path\'],$value[\'language_id\'],$server);\n				}\n			} elseif(isset($this->request->get[\'manufacturer_id\'])){\n				foreach ($results as $key => $value){\n					$this->session->data[\'hreflang\'][$value[\'language_id\']] = $this->nerdherd($server.\"index.php?route=product/manufacturer/info&manufacturer_id=\".$this->request->get[\'manufacturer_id\'],$value[\'language_id\'],$server);\n				}\n			} elseif(isset($this->request->get[\'information_id\'])){\n				foreach ($results as $key => $value){\n					$this->session->data[\'hreflang\'][$value[\'language_id\']] = $this->nerdherd($server.\"index.php?route=information/information&information_id=\".$this->request->get[\'information_id\'],$value[\'language_id\'],$server);\n				}\n			}elseif(isset($this->request->get[\'route\'])){\n				foreach($results as $key => $value){\n					$this->session->data[\'hreflang\'][$value[\'language_id\']] = $this->nerdherd($server.\"index.php?route=\".$this->request->get[\'route\'],$value[\'language_id\'],$server);\n			}\n\n			}\n			]]>\n			</add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/common/home.php\">\n		<operation>\n			<search><![CDATA[$this->document->addLink($this->config->get(\'config_url\'), \'canonical\');]]></search>\n			<add position=\"replace\"><![CDATA[\n			$this->load->model(\"tool/redirect\");\n			$homeurl =  $this->model_tool_redirect->getHoneUrl();\n			if($homeurl) {\n				$this->document->addLink($this->config->get(\'config_url\').$homeurl, \'canonical\');\n			} else {\n				$this->document->addLink($this->config->get(\'config_url\'), \'canonical\');\n			}\n			 ]]></add>\n		</operation>\n	</file>\n\n		<file path=\"catalog/controller/common/home.php\">\n		<operation>\n			<search><![CDATA[$data[\'column_left\'] = $this->load->controller(\'common/column_left\');]]></search>\n			<add position=\"before\"><![CDATA[$this->load->controller(\"common/seo_content\");]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/product/manufacturer.php\">\n		<operation>\n			<search><![CDATA[$pagination = new Pagination();]]></search>\n			<add position=\"before\"><![CDATA[$this->load->controller(\"common/seo_content\");]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/information/contact.php\">\n		<operation>\n			<search><![CDATA[if (isset($this->request->post[\'enquiry\'])) {]]></search>\n			<add position=\"before\"><![CDATA[$this->load->controller(\"common/seo_content\");]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/information/sitemap.php\">\n		<operation>\n			<search><![CDATA[$data[\'column_left\'] = $this->load->controller(\'common/column_left\');]]></search>\n			<add position=\"before\"><![CDATA[$this->load->controller(\"common/seo_content\");]]></add>\n		</operation>\n	</file>\n	<file path=\"catalog/controller/account/account.php,catalog/controller/account/login.php,catalog/controller/account/register.php,catalog/controller/account/order.php\">\n		<operation>\n			<search><![CDATA[$data[\'column_left\'] = $this->load->controller(\'common/column_left\');]]></search>\n			<add position=\"before\"><![CDATA[$this->load->controller(\"common/seo_content\");]]></add>\n		</operation>\n	</file>\n\n</modification>',1,'2017-04-27 01:13:33'),(4,'Fix Filter Opencart 2.x','fixfilter','AlexDW','1.00','https://www.opencart.com/index.php?route=marketplace/extension&filter_member=AlexDW','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<modification>\r\n	<name>Fix Filter Opencart 2.x</name>\r\n	<version>1.00</version>\r\n	<author>AlexDW</author>\r\n	<link>https://www.opencart.com/index.php?route=marketplace/extension&amp;filter_member=AlexDW</link>\r\n	<code>fixfilter</code>\r\n	<file path=\"catalog/model/catalog/product.php\">		\r\n		<operation error=\"abort\">\r\n		<search><![CDATA[\r\n$sql .= \" AND pf.filter_id IN (\" . implode(\',\', $implode) . \")\";\r\n			]]></search>\r\n			<add position=\"after\" ><![CDATA[\r\n// FixFilter\r\n			$minq=$this->db->query(\"\r\nSELECT id.product_id FROM(SELECT \r\n    product_id, count(i.product_id) as t, c.filter_group as b\r\nFROM\r\n    (SELECT \r\n        f.filter_id, f.product_id, p.filter_group_id\r\n    FROM\r\n        \". DB_PREFIX .\"product_filter f\r\n    left join \". DB_PREFIX .\"filter p ON p.filter_id = f.filter_id\r\n    where\r\n        p.filter_id IN (\" . implode(\',\', $implode) . \")\r\n    GROUP BY product_id , filter_group_id) as i,\r\n    (select \r\n        count(distinct filter_group_id) as filter_group\r\n    from\r\n        \". DB_PREFIX .\"filter_description f_b\r\n    WHERE f_b.filter_id in (\" . implode(\',\', $implode) . \")) as c\r\nGROUP BY product_id\r\nHAVING t = b) as id\");\r\n\r\n$min=array();\r\n\r\nfor($x=0;$x<count($minq->rows);$x++){	\r\n	\r\n	foreach($minq->rows[$x] as $value){\r\n		$min[]=$value;\r\n	}\r\n}\r\n\r\n$imp=implode(\',\',$min);\r\n// FixFilter END\r\n			]]></add>\r\n		</operation>\r\n\r\n		<operation error=\"abort\">\r\n		<search><![CDATA[\r\n$sql .= \" AND p.manufacturer_id = \'\" . (int)$data[\'filter_manufacturer_id\'] . \"\'\";\r\n			]]></search>\r\n			<add position=\"after\" offset=\"1\"><![CDATA[\r\n// FixFilter\r\n			if(isset($filters)){\r\n				if(!count($min)){\r\n					$imp=\'0000000\';\r\n				}\r\n			$sql .= \" AND p.product_id IN(\".$imp.\")\";\r\n			}\r\n// FixFilter END\r\n			]]></add>\r\n		</operation>\r\n	</file>\r\n</modification>',1,'2017-06-02 07:39:32');
